#!/usr/bin/env python3
"""Probe /workspace/executable with malformed snippets; extract pest 'expected' lists."""
import json
import re
import subprocess
import sys

BIN = "/workspace/executable"
POS_RE = re.compile(r"-->\s*(\d+):(\d+)")
EXP_RE = re.compile(r"=\s*expected\s+(.*)$")


def parse_expected(text):
    s = text.strip()
    # pest formats: "a", "a or b", "a, b, or c"
    if ", or " in s:
        head, last = s.rsplit(", or ", 1)
        parts = [p.strip() for p in head.split(",")] + [last.strip()]
    elif " or " in s:
        parts = [p.strip() for p in s.split(" or ")]
    else:
        parts = [s]
    return [p for p in parts if p]


def probe(snippet, timeout=5):
    try:
        p = subprocess.run([BIN, "-c", snippet], stdin=subprocess.DEVNULL,
                           capture_output=True, text=True, timeout=timeout)
    except subprocess.TimeoutExpired:
        return {"snippet": snippet, "status": "TIMEOUT"}
    err = p.stderr
    if "parse error" not in err:
        return {"snippet": snippet, "status": "OK" if p.returncode != 255 else "ERR",
                "rc": p.returncode, "stderr": err.strip()[:200]}
    pos = POS_RE.search(err)
    exp = None
    for line in err.splitlines():
        m = EXP_RE.search(line)
        if m:
            exp = parse_expected(m.group(1))
            break
    return {"snippet": snippet, "status": "PARSE_ERR",
            "pos": f"{pos.group(1)}:{pos.group(2)}" if pos else "?",
            "expected": exp,
            "raw": err.strip()}


def main():
    with open(sys.argv[1]) as f:
        snippets = [json.loads(l) for l in f if l.strip()]
    out = []
    seen = set()
    for s in snippets:
        if s in seen:
            continue
        seen.add(s)
        out.append(probe(s))
    with open(sys.argv[2], "w") as f:
        for r in out:
            f.write(json.dumps(r) + "\n")
    n = sum(1 for r in out if r["status"] == "PARSE_ERR")
    print(f"{len(out)} snippets, {n} parse errors", file=sys.stderr)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Collect distinct expected-lists, build order constraints, topo-sort, verify."""
import json
import sys
from collections import defaultdict


def load(paths):
    recs = []
    for p in paths:
        with open(p) as f:
            for line in f:
                if line.strip():
                    recs.append(json.loads(line))
    return recs


def main():
    recs = [r for r in load(sys.argv[1:]) if r.get("status") == "PARSE_ERR" and r.get("expected")]
    lists = {}
    for r in recs:
        key = ",".join(r["expected"])
        if key not in lists:
            lists[key] = r
    print(f"# {len(recs)} parse errors, {len(lists)} distinct lists", file=sys.stderr)

    rules = set()
    succ = defaultdict(set)  # a -> set of b with a<b
    for key in lists:
        L = key.split(",")
        rules.update(L)
        for i in range(len(L)):
            for j in range(i + 1, len(L)):
                succ[L[i]].add(L[j])

    # contradiction check
    bad = []
    for a in succ:
        for b in succ[a]:
            if a in succ.get(b, ()):
                bad.append((a, b))
    if bad:
        print("!!! CONTRADICTIONS:", sorted(set(tuple(sorted(x)) for x in bad)), file=sys.stderr)

    # topo sort: deterministic - repeatedly pick a rule with no unplaced predecessor,
    # tie-break by (number of successors desc) then name, to be stable
    pred = defaultdict(set)
    for a in succ:
        for b in succ[a]:
            pred[b].add(a)
    remaining = set(rules)
    order = []
    while remaining:
        avail = [r for r in remaining if not (pred[r] & remaining)]
        if not avail:
            print("!!! CYCLE among:", sorted(remaining), file=sys.stderr)
            break
        # tie-break: more successors => earlier (heuristic); then alphabetical
        avail.sort(key=lambda r: (-len(succ[r] & remaining), r))
        pick = avail[0]
        order.append(pick)
        remaining.discard(pick)

    pos = {r: i for i, r in enumerate(order)}
    # verify
    fails = []
    for key in lists:
        L = key.split(",")
        if sorted(L, key=lambda r: pos[r]) != L:
            fails.append(key)
    print(f"# order size {len(order)}; verification failures: {len(fails)}", file=sys.stderr)
    for f in fails:
        print("  FAIL:", f, file=sys.stderr)

    # ambiguity report: pairs with no constraint either way
    unconstrained = []
    ro = order
    for i in range(len(ro)):
        for j in range(i + 1, len(ro)):
            a, b = ro[i], ro[j]
            if b not in succ[a] and a not in succ[b]:
                unconstrained.append((a, b))
    print(f"# unconstrained pairs: {len(unconstrained)}", file=sys.stderr)
    # only report adjacent-ish unconstrained
    adj = [(a, b) for (a, b) in unconstrained if abs(pos[a] - pos[b]) == 1]
    print("# adjacent unconstrained:", adj, file=sys.stderr)

    json.dump({"order": order,
               "lists": {k: {"snippet": v["snippet"], "pos": v["pos"]} for k, v in lists.items()},
               "unconstrained": unconstrained},
              open("/tmp/probe/analysis.json", "w"), indent=1)
    for i, r in enumerate(order):
        print(f"{i}\t{r}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Parallel probe runner."""
import json
import re
import subprocess
import sys
from concurrent.futures import ThreadPoolExecutor

BIN = "/workspace/executable"
POS_RE = re.compile(r"-->\s*(\d+):(\d+)")
EXP_RE = re.compile(r"=\s*expected\s+(.*)$")


def parse_expected(text):
    s = text.strip()
    if ", or " in s:
        head, last = s.rsplit(", or ", 1)
        parts = [p.strip() for p in head.split(",")] + [last.strip()]
    elif " or " in s:
        parts = [p.strip() for p in s.split(" or ")]
    else:
        parts = [s]
    return [p for p in parts if p]


def probe(snippet):
    try:
        p = subprocess.run([BIN, "-c", snippet], stdin=subprocess.DEVNULL,
                           capture_output=True, text=True, timeout=5)
    except subprocess.TimeoutExpired:
        return {"snippet": snippet, "status": "TIMEOUT"}
    except Exception as e:
        return {"snippet": snippet, "status": "EXC", "err": str(e)}
    err = p.stderr
    if "parse error" not in err:
        return {"snippet": snippet, "status": "OK", "rc": p.returncode,
                "stderr": err.strip()[:160]}
    pos = POS_RE.search(err)
    exp = None
    for line in err.splitlines():
        m = EXP_RE.search(line)
        if m:
            exp = parse_expected(m.group(1))
            break
    return {"snippet": snippet, "status": "PARSE_ERR",
            "pos": f"{pos.group(1)}:{pos.group(2)}" if pos else "?",
            "expected": exp}


def main():
    snippets = []
    seen = set()
    for path in sys.argv[1:-1]:
        with open(path) as f:
            for line in f:
                if not line.strip():
                    continue
                s = json.loads(line)
                if s not in seen:
                    seen.add(s)
                    snippets.append(s)
    with ThreadPoolExecutor(max_workers=16) as ex:
        out = list(ex.map(probe, snippets))
    with open(sys.argv[-1], "w") as f:
        for r in out:
            f.write(json.dumps(r) + "\n")
    n = sum(1 for r in out if r["status"] == "PARSE_ERR")
    t = sum(1 for r in out if r["status"] == "TIMEOUT")
    print(f"{len(out)} snippets, {n} parse errors, {t} timeouts", file=sys.stderr)


if __name__ == "__main__":
    main()
